package com.bank.dsa;

import java.math.BigInteger;
import java.util.logging.*;

// Runnable demo: sum of first 10 natural numbers, loop vs closed form.
public class SumFirstTenDemo {
    private static final Logger log = Logger.getLogger(SumFirstTenDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SeriesSum series = new SeriesSum();

        int n = 10;
        BigInteger viaLoop    = series.sumToN(n);
        BigInteger viaFormula = series.sumToNFormula(n);
        log.info(() -> "Sum 1.." + n + " via loop    = " + viaLoop);
        log.info(() -> "Sum 1.." + n + " via formula = " + viaFormula);
    }
}

// ─── Would be in SeriesSum.java in a real project ───
class SeriesSum {
    // Loop version: sum = 0; for i = 1..N { sum += i }.
    BigInteger sumToN(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("N must be non-negative: " + n);
        }
        BigInteger sum = BigInteger.ZERO;             // seed = additive identity
        for (int i = 1; i <= n; i++) {                // loop while i <= N
            sum = sum.add(BigInteger.valueOf(i));
        }
        return sum;
    }

    // Closed form: N*(N+1)/2 -> constant time, exact (product is always even).
    BigInteger sumToNFormula(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("N must be non-negative: " + n);
        }
        BigInteger bn = BigInteger.valueOf(n);
        return bn.multiply(bn.add(BigInteger.ONE)).divide(BigInteger.TWO);
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
